    WORD word(size_t p)const{if(p>b.size()||b.size()-p<2)throw std::runtime_error("Truncated PE word");WORD x;memcpy(&x,b.data()+p,2);return x;}
    DWORD dword(size_t p)const{if(p>b.size()||b.size()-p<4)throw std::runtime_error("Truncated PE DWORD");DWORD x;memcpy(&x,b.data()+p,4);return x;}
