    IMAGE_NT_HEADERS32& nt(){return *(IMAGE_NT_HEADERS32*)(b.data()+ntOff);}
    const IMAGE_NT_HEADERS32& nt()const{return *(const IMAGE_NT_HEADERS32*)(b.data()+ntOff);}
    unsigned sections()const{return word(ntOff+6);}
    IMAGE_SECTION_HEADER section(unsigned i)const{if(i>=sections())throw std::runtime_error("Bad section index");IMAGE_SECTION_HEADER s;memcpy(&s,b.data()+secOff+i*40,40);return s;}
    size_t offset(DWORD rva,size_t n=1)const{for(unsigned i=0;i<sections();++i){auto s=section(i);if(rva>=s.VirtualAddress&&rva-s.VirtualAddress<s.SizeOfRawData){size_t p=s.PointerToRawData+rva-s.VirtualAddress;if(n>s.SizeOfRawData-(rva-s.VirtualAddress)||p>b.size()||n>b.size()-p)throw std::runtime_error("RVA outside raw section");return p;}}if(rva<nt().OptionalHeader.SizeOfHeaders&&rva<=b.size()&&n<=b.size()-rva)return rva;throw std::runtime_error("Unmapped PE RVA");}
