    void reserveHeaders(unsigned extra){DWORD need=align(secOff+(sections()+extra)*40,nt().OptionalHeader.FileAlignment),old=nt().OptionalHeader.SizeOfHeaders;if(need<=old)return;DWORD delta=need-old;b.insert(b.begin()+old,delta,0);nt().OptionalHeader.SizeOfHeaders=need;for(unsigned i=0;i<sections();++i){auto s=section(i);if(s.PointerToRawData)s.PointerToRawData+=delta;if(s.PointerToRelocations)s.PointerToRelocations+=delta;if(s.PointerToLinenumbers)s.PointerToLinenumbers+=delta;memcpy(b.data()+secOff+i*40,&s,40);}if(nt().FileHeader.PointerToSymbolTable)nt().FileHeader.PointerToSymbolTable+=delta;auto& security=nt().OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_SECURITY];if(security.VirtualAddress)security.VirtualAddress+=delta;auto debug=nt().OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_DEBUG];if(debug.VirtualAddress)for(DWORD p=0;p+sizeof(IMAGE_DEBUG_DIRECTORY)<=debug.Size;p+=sizeof(IMAGE_DEBUG_DIRECTORY)){auto off=offset(debug.VirtualAddress+p,sizeof(IMAGE_DEBUG_DIRECTORY));auto d=(IMAGE_DEBUG_DIRECTORY*)(b.data()+off);if(d->PointerToRawData)d->PointerToRawData+=delta;}}
